import{_ as s,o as t,c as a,a3 as i}from"./chunks/framework.uTHcANy5.js";const k=JSON.parse('{"title":"Federating","description":"","frontmatter":{},"headers":[],"relativePath":"tools/federate.md","filePath":"tools/federate.md"}'),n={name:"tools/federate.md"};function o(r,e,h,d,p,l){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="federating" tabindex="-1">Federating <a class="header-anchor" href="#federating" aria-label="Permalink to &quot;Federating&quot;">​</a></h1><p><code>mosaic federate</code> layers one archive over another and writes the result as one archive:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mosaic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> federate</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">old.ts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">new.ts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [output.tsr] [--collapse]</span></span></code></pre></div><p>Without an output path, the result is written next to the new archive as <code>&lt;new&gt;.federated.tsr</code>.</p><p>The new archive&#39;s sections go <strong>over</strong> the old one&#39;s. Where both say something about the same component of the same node, the new archive wins: its values replace the old ones, and its <code>DELETE</code>s remove them. Everything only one of them mentions comes through as it is.</p><table tabindex="0"><thead><tr><th></th><th>Keeps</th></tr></thead><tbody><tr><td>default</td><td><strong>Every section of both</strong>, in order: the full history, with every row either of them had</td></tr><tr><td><code>--collapse</code></td><td>Only what is <strong>still leading</strong>: each component&#39;s current value, under the section that wrote it. Superseded rows, and tables left empty, are dropped</td></tr></tbody></table><p>Both archives&#39; imports are kept, the old archive&#39;s first and each one once. A component type both carry gets one table, described by the newer archive&#39;s schema.</p><h2 id="applying-a-diff" tabindex="-1">Applying a diff <a class="header-anchor" href="#applying-a-diff" aria-label="Permalink to &quot;Applying a diff&quot;">​</a></h2><p>Federating is how a diff from <a href="/mosaic/dist/docs/tools/diff"><code>mosaic diff</code></a> is applied. The result reads the same as the archive the diff was made from:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-1" id="tab-1-1" checked><label data-title="round trip" for="tab-1-1">round trip</label><input type="radio" name="group-1" id="tab-1-2"><label data-title="output" for="tab-1-2">output</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mosaic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">     house-v1.tsr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> house-v2.tsr</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # -&gt; house-v2.diff.tsr</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mosaic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> federate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> house-v1.tsr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> house-v2.diff.tsr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> house.tsr</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # house.tsr reads as house-v2.tsr</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mosaic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">     house-v2.tsr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> house.tsr</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # No changes.</span></span></code></pre></div><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Sections: 2</span></span>
<span class="line"><span>Nodes: 3</span></span>
<span class="line"><span>Component rows: 5</span></span></code></pre></div></div></div><p>With <code>--collapse</code>, the same round trip gives a smaller archive with the same contents: here 3 component rows instead of 5.</p><h2 id="federating-versus-importing" tabindex="-1">Federating versus importing <a class="header-anchor" href="#federating-versus-importing" aria-label="Permalink to &quot;Federating versus importing&quot;">​</a></h2><p>An <a href="/mosaic/dist/docs/welcome/definitions#import">import</a> keeps two archives separate: each is still published, versioned and owned on its own, and they&#39;re layered only when they&#39;re read. Federating merges them into one file for good. Use it to apply changes, or to hand someone a single file, not to build a scene from parts other people own.</p><p>The merge is <code>federate</code> in the SDK (<a href="https://github.com/tomvandig/mosaic/blob/main/sdk/ts/src/MosaicFileOperations.ts" target="_blank" rel="noreferrer">source</a>). <code>mosaic compose</code> uses it too, to layer an archive over its imports before drawing them.</p>`,14)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
